Đáp án: ```cpp
void BFS ()
{
    Node* current = root;
    queue<Node*> bfq;
    int cnt = 0;
    while (current != NULL)
    {
        if (cnt == 0) {cout << current->value;++cnt;}
        else cout << " " << current->value;
        if (current ->pLeft != NULL) bfq.push(current->pLeft);
        if (current->pRight != NULL) bfq.push(current->pRight);
        if (!bfq.empty()) {current = bfq.front(); bfq.pop();}
        else current = NULL;
    }
}
