Đáp án: ```cpp
int maxDepth(Node* root)
{
    if (root == NULL) return 0;
    if (root->pLeft == NULL && root->pRight == NULL) return 1;
    int left_depth = maxDepth(root->pLeft);
    int right_depth = maxDepth(root->pRight);
    if (left_depth > right_depth) return left_depth + 1;
    return right_depth + 1;
}
//Helping functions
int getDiameter(){
    if (root == NULL) return 0;
    int maxLeft = maxDepth(root->pLeft);
    int maxRight = maxDepth(root->pRight);
    return maxLeft + maxRight + 1;
}
