        // update maximum length and maximum sum
        // according to the given conditions
        if (maxLen < len) {
            maxLen = len;
            maxSum = sum;
        } else if (maxLen == len && maxSum < sum)
            maxSum = sum;
            return;
    }
    sumOfLongRootToLeafPath(root->left, sum + root->val,len + 1, maxLen, ma
    sumOfLongRootToLeafPath(root->right, sum + root->val,len + 1, maxLen, m
}
