INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8c6dc277-72a9-552c-94c2-ce097b9bf3cb', '96f84afd-eb71-59af-bbd4-1f86065c5c75',
  'Class `BTreeNode` is used to store a node in a binary tree, described as follows:

```cpp
class BTreeNode {
    public:
        int val;
        BTreeNode *left;
        BTreeNode *right;
        BTreeNode() {
            this->left = this->right = NULL;
        }
        BTreeNode(int val) {
            this->val = val;
            this->left = this->right = NULL;
        }
        BTreeNode(int val, BTreeNode*& left, BTreeNode*& right) {
            this->val = val;
            this->left = left;
            this->right = right;
        }
};
```

Where `val` is the value of the node (a non-negative integer), and `left` and `right` are pointers to its left and right nodes, respectively.

**Request:** Implement the function:

```cpp
int largestDiff(BTreeNode* root);
```

Here, `root` is the root node of the given binary tree. The tree has between 2 and 100,000 elements. This function returns the largest absolute difference between any node and its descendants.

**More information:** A node is also considered a descendant of itself.

**Example:**

Given a binary tree with the following nodes:

- `0` (root)
- `4` (left child of `0`)
- `2` (right child of `0`)
- `1` (left child of `2`)
- `7` (right child of `2`)
- `6` (left child of `1`)
- `3` (right child of `1`)

The largest absolute difference is between node `0` and node `7`; therefore, return `7`.

**Note:** In this exercise, the libraries `iostream`, `stack`, `queue`, `utility` and `using namespace std` are used. You may write helper functions; however, you are not allowed to use other libraries.

**For example:**

| Test | Result |
| :--- | :--- |
| `int arr[] = {-1,0,0,2,2,3,3};`<br>`int value[] = {0,4,2,1,7,6,3};`<br>`BTNode* root = BTNode::createTree(arr, arr + sizeof(arr)/sizeof(int), value);`<br>`cout << largestDiff(root) << "\n";` | 7 |
| `int arr[] = {-1,0};`<br>`int value[] = {1,0};`<br>`BTNode* root = BTNode::createTree(arr, arr + sizeof(arr)/sizeof(int), value);`<br>`cout << largestDiff(root) << "\n";` | 1 |

Đáp án: ```cpp
int ans = -1;
void inn(BTNode * curr,BTNode *head)
{

  if(!curr) return ;
  inn(curr->left,head);
  ans = max(ans,abs(head->val-curr->val));
  inn(curr->right,head);
}
void in(BTNode * curr)
{
  if(!curr)
  return ;
  in(curr->left);
  inn(curr,curr);
  in(curr->right);
}
stack<int> getElement (BTNode* root)
{
    stack<int> res;
    BTNode* current = root;
    queue<BTNode*> bfq;

    while (current != NULL)
    {
      res.push(current->val);
      if (current ->left != NULL) bfq.push(current->left);
      if (current->right != NULL) bfq.push(current->right);
      if (!bfq.empty()) {current = bfq.front(); bfq.pop();}
      else current = NULL;
    }
    return res;
}
int largestDiff(BTNode* root) {
  if (root == NULL) return 0;
  stack<int> arr = getElement(root);
  if ((int)arr.size() == 2)
  {
    int a = arr.top();
    arr.pop();
    int b = arr.top();
    return abs(a-b);
  }
  if ((int)arr.size() == 1)
  {
    return abs(arr.top());
  }
  in(root);

  return ans;
}
```', 4
);

